<script setup lang="ts">import {ref,computed} from 'vue';import type {Run,Profile,User} from '../types/domain';import {researchApi} from '../api/research';import {useAsync} from '../hooks/useAsync';import PageTitle from '../components/common/PageTitle.vue';import Badge from '../components/common/Badge.vue';import Empty from '../components/common/Empty.vue';import Notice from '../components/common/Notice.vue';import Table from '../components/common/Table.vue';import TopicTerms from '../components/TopicTerms.vue';import RunSummary from '../components/RunSummary.vue';import AlignmentGrid from '../components/AlignmentGrid.vue';import {pct,dec} from '../utils/format';const props=defineProps<{runs:Run[];profiles:Profile[];selectedId:number;user:User;reload:()=>Promise<any>}>();const emit=defineEmits<{select:[run:Run]}>();const run=computed(()=>props.runs.find(r=>r.id===props.selectedId)||props.runs[0]),topics=computed(()=>props.profiles.filter(p=>p.run_id===run.value?.id)),focusId=ref(0),focus=computed(()=>topics.value.find(p=>p.id===focusId.value)||topics.value[0]),label=ref('人工主题A'),editorNote=ref('结合词权和代表文档人工命名，非模型自动语义结论。'),noteName=ref('展签主题编辑说明'),interpretation=ref('相对激活用于代表文档阅读；对齐稳定仅反映初始化敏感性，不等于语义真值。'),nextStep=ref('逐篇阅读混合主题摘要，与策展编辑核对命名和改稿范围。');const {task,act}=useAsync();</script><template><template v-if="run"><PageTitle index="04 / WORDS & STABILITY" title="读词权，也读初始化的变化。" description="主题编号只是参照分解的位置，主题名由编辑给出；相对激活权重不称概率后验。完整W/H和匹配随运行保留。"/><Notice :error="task.error||run.error" :message="task.message"/><div class="run-selector"><select aria-label="选择运行" :value="run.id" @change="emit('select',runs.find(r=>r.id===Number(($event.target as HTMLSelectElement).value))!)"><option v-for="r in runs" :key="r.id" :value="r.id">{{r.name}}</option></select><Badge :status="run.status"/><small>SHA-256 {{run.result.fingerprint?.slice(0,26)||'等待计算'}}…</small></div><template v-if="topics.length"><RunSummary :run="run"/><div class="topic-layout"><section><div class="topic-tabs"><button v-for="p in topics" :key="p.id" :class="{active:p.id===focus?.id}" @click="focusId=p.id">{{p.topic_index+1}} / {{p.label}}</button></div><TopicTerms v-if="focus" :profile="focus"/></section><aside class="normalization-note"><small>SCALE / RECONSTRUCTION</small><h2>{{dec(run.result.baseline_relative_error)}}</h2><p>参照seed {{run.result.reference_seed}}的相对Frobenius误差，仅解释固定语料与K下的拟合，不作跨K自动最优或语义质量分数。</p><p>H每行词权和为1；W乘相应范数，归一前后WH一致。有效{{run.result.effective_documents}}篇，空词排除{{run.result.excluded_documents?.length}}篇。</p><p>平均匹配余弦来自其余{{run.config.repeats-1}}次独立重拟合，不含参照自身1.0。</p></aside></div><form v-if="focus&&user.role!=='viewer'" class="editor naming-editor" @submit.prevent="act(async()=>{await researchApi.name(focus!.id,{label,editor_note:editorNote});await reload()},'人工主题名已保存')"><h2>编辑命名 / 当前主题{{focus.topic_index+1}}</h2><div class="form-grid"><label>人工主题名称<input v-model="label" required maxlength="100"/></label><label>命名依据<input v-model="editorNote" maxlength="500"/></label></div><button class="primary" :disabled="task.busy">保存人工命名 →</button></form><AlignmentGrid :run="run"/><div class="section-title"><h2>文档相对激活 / 非后验概率</h2><small>参照分解前20有效文档</small></div><Table :headers="['文档 / 标题',...topics.map(p=>p.label)]"><tr v-for="d in run.result.document_topics?.slice(0,20)" :key="d.id"><td><small>{{d.reference}}</small><strong>{{d.title}}</strong></td><td v-for="p in topics" :key="p.id">{{d.relative_activation?pct(d.relative_activation[p.topic_index]):'未激活'}}</td></tr></Table><div class="section-title"><h2>冻结词汇、idf与空词记录</h2><small>idf文档总量{{run.result.idf_n_documents}}，包含空词</small></div><div class="vocabulary-grid"><div v-for="(word,i) in run.result.vocabulary" :key="word"><strong>{{word}}</strong><small>df {{run.result.document_frequency?.[i]}} / idf {{dec(run.result.idf?.[i])}}</small></div></div><p class="excluded-note">排除文档：{{run.result.excluded_documents?.map(d=>d.reference+' '+d.reason).join('；')||'无'}}。参数：raw TF，ln((1+n)/(1+df))+1，L2，min_df={{run.config.min_df}}。</p><form v-if="focus&&user.role!=='viewer'" class="editor note-editor" @submit.prevent="act(async()=>{await researchApi.note({run_id:run!.id,name:noteName,profile_ids:[focus!.id],interpretation,next_step:nextStep});await reload()},'编辑说明已建立，等待负责人审阅')"><small>NEXT / EDITORIAL RECORD</small><h2>以当前人工主题建立说明</h2><label>说明名称<input v-model="noteName" required maxlength="100"/></label><label>编辑解释<textarea v-model="interpretation" rows="3" required maxlength="700"/></label><label>下一步阅读与改稿<input v-model="nextStep" required maxlength="500"/></label><p>建立时冻结主题名、词权与稳定性快照，后续命名修订不会改写已审阅交付。</p><button class="primary" :disabled="task.busy">建立编辑说明 →</button></form></template><Empty v-else title="等待worker或检查失败原因" help="空词、常量/低秩、不可行K或任一未收敛会明确failed；调整输入与参数后重新运行。"/></template><Empty v-else title="尚无主题册" help="从主题配置选择K与独立初始化次数。"/></template>
